oup"><label for="starts_at">Start <span class="field-label-note">Optional</span></label><input id="starts_at" name="starts_at" type="datetime-local" value="<?=old_value($old,'starts_at',$date('starts_at'))?>"<?=$invalid('starts_at')?>></div><div class="field-group"><label for="ends_at">End <span class="field-label-note">Optional</span></label><input id="ends_at" name="ends_at" type="datetime-local" value="<?=old_value($old,'ends_at',$date('ends_at'))?>"<?=$invalid('ends_at')?>><?php if($m=field_error($errors,'ends_at')):?><p id="ends-at-error" class="field-error" role="alert"><?=e($m)?></p><?php endif;?></div><div class="field-group"><label for="sort_order">Sort order</label><input id="sort_order" name="sort_order" type="number" min="0" max="1000000" value="<?=$value('sort_order','0')?>" required<?=$invalid('sort_order')?>></div></div></section><div class="organizer-form__actions"><p><i class="ph ph-info" aria-hidden="true"></i><span>New banners start active. Status changes remain separate.</span></p><button class="button button--primary" type="submit"><i class="ph ph-floppy-disk" aria-hidden="true"></i><span><?= $edit?'Save banner':'Create banner' ?></span></button></div></form>
